FREQS_KHZ = sorted(CURVES_BY_FREQ_KHZ)


def _interp(points, x):
    """Linear-interpolate y at x over a sorted (x, y) point list."""
    if x <= points[0][0]:
        return points[0][1]
    if x >= points[-1][0]:
        return points[-1][1]
    for (x0, y0), (x1, y1) in zip(points, points[1:]):
        if x0 <= x <= x1:
            frac = (x - x0) / (x1 - x0)
            return y0 + frac * (y1 - y0)
    return points[-1][1]


def curve_km_vs_dbu(freq_khz):
    """Return [(distance_km, field_strength_dbu), ...] at 1 kW for
    freq_khz, interpolating between the two nearest of FCC's 20
    representative frequency graphs.
    """
    freq_khz = min(max(freq_khz, FREQS_KHZ[0]), FREQS_KHZ[-1])
    if freq_khz in CURVES_BY_FREQ_KHZ:
        return CURVES_BY_FREQ_KHZ[freq_khz]
    lo = max(f for f in FREQS_KHZ if f < freq_khz)
    hi = min(f for f in FREQS_KHZ if f > freq_khz)
    frac = (freq_khz - lo) / (hi - lo)
    hi_points = CURVES_BY_FREQ_KHZ[hi]
    result = []
    for km, dbu_lo in CURVES_BY_FREQ_KHZ[lo]:
        dbu_hi = _interp(hi_points, km)
        result.append((km, dbu_lo + frac * (dbu_hi - dbu_lo)))
    return result
